-- Study Abroad country content, BATCH 3: Spain, Italy, Singapore, Sweden, Malaysia.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('spain', 'italy', 'singapore', 'sweden', 'malaysia'));
UPDATE countries SET why_title = 'Why study in Spain?', why_body = '<p>Spain combines affordable study with a warm climate, a rich culture and a growing number of English-taught programmes. It is known for strong business schools, architecture, tourism and hospitality, and design.</p><ul><li>Public university tuition is low compared with the UK, US and Australia</li><li>Spanish is the world''s second most spoken native language, a useful skill for global careers</li><li>Business schools such as IE, IESE and ESADE are known internationally</li><li>Student visa holders may work part time while studying</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students need a <strong>national student visa (type D)</strong> from the Spanish consulate in their country if the course is longer than 90 days. After arrival you apply for a student residence card (TIE).</p><ul><li>Admission letter or proof of enrolment from a Spanish institution</li><li>Proof of funds: reported at 100% of the IPREM, about €600 a month (about €7,200 for 12 months), with extra for family members</li><li>Health insurance valid in Spain with no co-payments</li><li>Criminal record certificate and a medical certificate, usually apostilled or legalised</li><li>Work: students may work up to about 30 hours a week (reported)</li><li>After graduation: a post-study permit to look for work or start a business (check the current length with the consulate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Spanish Ministry of Foreign Affairs (exteriores.gob.es) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Private universities and business schools take applications directly. Public universities may require non-EU applicants to have their school credentials validated through <strong>UNEDasiss</strong> before applying.</p><ul><li>Academic transcripts and certificates, often translated and apostilled</li><li>Proof of English or Spanish proficiency</li><li>CV and motivation letter for Master''s programmes</li><li>GMAT/GRE for some business programmes</li><li>Passport copy</li><li>Portfolio or entrance test for architecture and design courses</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees vary widely between public universities, private universities and business schools. Madrid and Barcelona are the most expensive cities.</p><ul><li>Public universities: tuition is set by each region and is usually lower than in other Western European countries; non-EU students may pay more</li><li>Private universities and business schools: roughly €6,000-€30,000+ a year, depending on the course</li><li>Living costs: about €600-€1,200 a month depending on the city (IPREM funds guide is about €600)</li><li>Health insurance is mandatory and must be shown for the visa</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Entry requirements depend on the university and programme.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school; non-EU students usually need credential validation to enter public universities</li><li><strong>Master''s:</strong> a relevant bachelor''s degree; many programmes ask for a CV and motivation letter and some for GMAT/GRE</li><li><strong>Language:</strong> Spanish B2 (DELE or SIELE) for Spanish-taught courses; IELTS 6.0-6.5 or TOEFL 80+ for English-taught courses</li><li>Applicants must be at least 18 for a student visa</li></ul>' WHERE slug = 'spain';
UPDATE countries SET why_title = 'Why study in Italy?', why_body = '<p>Italy has some of the oldest universities in the world, low public tuition and global strengths in design, architecture, engineering, fashion, art and food. Many Master''s programmes are taught in English.</p><ul><li>Public university fees are set by income level and are generally low</li><li>Global reputation in architecture, design, fashion, engineering and arts</li><li>Large regional scholarship system for eligible students</li><li>A temporary permit to look for work after graduation</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students need a <strong>national study visa (type D)</strong>. You first complete <strong>pre-enrolment on the Universitaly portal</strong>, then apply at the Italian embassy or consulate (appointments through Prenot@mi or the visa centre). After arrival you apply for a residence permit (permesso di soggiorno).</p><ul><li>Universitaly pre-enrolment receipt and admission or eligibility letter</li><li>Proof of funds: reported at about €10,179.85 per year, plus funds for the return journey</li><li>Proof of accommodation in Italy for a set period and health insurance</li><li>Original and legalised or translated degree certificates</li><li>Residence permit: apply within 8 working days of arrival, then renew each year</li><li>Work: students may work part time (usually up to 20 hours a week)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Italian embassy or consulate site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You usually apply to each university''s own portal and also complete pre-enrolment on <strong>Universitaly</strong> for the visa. Some courses (for example medicine in English) have national entry tests.</p><ul><li>Academic transcripts and certificates, often translated and legalised</li><li>Declaration of Value or CIMEA statement of comparability for some universities</li><li>English or Italian language proof</li><li>CV and motivation letter for Master''s programmes</li><li>Entry test results (for example IMAT or TOLC) for limited-place courses</li><li>Passport copy</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public university fees depend on your family income and the university, and are usually lower than in other major study destinations. Private universities and business schools charge more.</p><ul><li>Public universities: tuition is calculated on income and typically ranges from a few hundred to a few thousand euros a year</li><li>Private universities and business schools: roughly €10,000-€25,000+ a year</li><li>Living costs: about €700-€1,200 a month depending on the city; Milan and Rome are the most expensive</li><li>Regional scholarships (DSU) can cover fees and offer a meal subsidy</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and programme.</p><ul><li><strong>Bachelor''s:</strong> a secondary diploma that gives access to university in your country; students from 11-year school systems may need a foundation year</li><li><strong>Master''s:</strong> a relevant bachelor''s degree, with specific credits in some subjects</li><li><strong>Language:</strong> Italian B2 (CILS, CELI, PLIDA) for Italian-taught courses; IELTS 5.5-6.5 or TOEFL for English-taught courses</li><li>Some programmes ask for entry tests or portfolios</li></ul>' WHERE slug = 'italy';
UPDATE countries SET why_title = 'Why study in Singapore?', why_body = '<p>Singapore is a safe, English-speaking global city with two of the world''s top universities. In the QS World University Rankings 2027, NUS is 10th and NTU 12th, making Singapore one of the strongest study destinations in Asia.</p><ul><li>World-leading universities in engineering, computing, science and business</li><li>A global hub for finance, technology and biomedical research</li><li>English is the language of instruction and business</li><li>Easy access to the rest of Asia</li></ul>', visa_title = 'Student''s Pass requirements', visa_body = '<p>International students need a <strong>Student''s Pass</strong> from the Immigration and Checkpoints Authority (ICA). Your institution registers you through the SOLAR system, and you complete the application online.</p><ul><li>Acceptance letter from an approved institution</li><li>Processing fee: S$45 (non-refundable); issuance fee S$60 after in-principle approval; S$30 for a Multiple Journey Visa if needed</li><li>Apply roughly 2-3 months before the course starts (ICA advice)</li><li>Passport, photos and supporting documents, plus a medical examination for courses over 6 months</li><li>In-principle approval letter is not the pass: you complete formalities with ICA after arrival</li><li>Work: university students may work part time during term (limits apply, so check with ICA)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official ICA Singapore site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university or institute. Undergraduate applications are made online, with deadlines early in the year.</p><ul><li>Academic transcripts and certificates</li><li>Proof of English proficiency</li><li>SAT, ACT or national exam results where required</li><li>Personal statement and references</li><li>Portfolio or audition for design and arts courses</li><li>Passport copy and Student''s Pass documents after admission</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees at the public universities depend on the course and your status. The government Tuition Grant lowers fees for international students but needs a commitment to work in Singapore after graduation.</p><ul><li>Tuition: varies by course and university; engineering, medicine and business cost more</li><li>MOE Tuition Grant: reduces fees but requires a work commitment in Singapore after graduation (3 years is typical)</li><li>Living costs: higher than in most Asian destinations; housing is the largest cost</li><li>Student''s Pass fees: S$45 processing plus S$60 issuance (S$30 extra for a Multiple Journey Visa)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Admission is competitive and depends on the university and course.</p><ul><li><strong>Bachelor''s:</strong> strong results in the final secondary school exams, often with maths and science; some courses need an interview or portfolio</li><li><strong>Master''s:</strong> a relevant bachelor''s degree with a strong grade; some courses need work experience or GRE/GMAT</li><li><strong>English:</strong> IELTS 6.5-7.0 or TOEFL 85-100 for most programmes</li><li>Students from approved countries may be exempt from the English test</li></ul>' WHERE slug = 'singapore';
UPDATE countries SET why_title = 'Why study in Sweden?', why_body = '<p>Sweden is known for innovation, sustainability and a flat, collaborative teaching style. Its universities are strong in engineering, medicine, design and environmental science, and many Master''s programmes are taught in English.</p><ul><li>Over 1,000 English-taught programmes at Master''s level</li><li>Home to companies such as Ericsson, Volvo, Spotify and H&M</li><li>Teaching based on group work and independent thinking</li><li>Graduates may apply for a permit to stay and look for work</li></ul>', visa_title = 'Student residence permit requirements', visa_body = '<p>Students from outside the EU/EEA and Switzerland need a <strong>residence permit for studies</strong> from the Swedish Migration Agency (Migrationsverket). You apply after you receive an admission letter, usually online.</p><ul><li>Admission letter and proof of paid tuition fee, where fees apply</li><li>Proof of funds: reported at SEK 10,656 a month for permits applied for in 2026, held in your own account (sponsor funds are not accepted)</li><li>Health insurance valid in Sweden</li><li>Application fee: about SEK 1,500</li><li>Work: new rules in 2026 limit student work (reported at 15 hours a week for permits granted from 11 June 2026 for Bachelor''s and Master''s students)</li><li>Graduates may apply for a permit of up to 12 months to look for work</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Swedish Migration Agency (migrationsverket.se) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Most students apply through <strong>universityadmissions.se</strong>. You choose up to several programmes and submit documents once for all.</p><ul><li>Application fee: SEK 900 (for non-EU/EEA applicants)</li><li>Academic transcripts and certificates</li><li>English proficiency proof (IELTS, TOEFL or equivalent)</li><li>CV and motivation letter for Master''s programmes</li><li>Letters of recommendation for some programmes</li><li>Passport copy</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition is free for EU/EEA students but not for non-EU students. Living costs are high but students get discounts.</p><ul><li>Tuition (non-EU): roughly SEK 80,000-190,000 a year, depending on the course</li><li>Living costs: about SEK 10,656 a month is the migration guide for 2026</li><li>Application fee: SEK 900 for universityadmissions.se, plus about SEK 1,500 for the residence permit</li><li>Scholarships can cover tuition and part of the living costs</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the programme and university.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school, with specific subjects (such as mathematics or English) for some courses</li><li><strong>Master''s:</strong> a bachelor''s degree (usually 180 ECTS-equivalent credits) in a related field</li><li><strong>English:</strong> IELTS 6.5 overall, or TOEFL 90+, for most programmes</li><li>Applicants from outside the EU/EEA must pay the application and tuition fees</li></ul>' WHERE slug = 'sweden';
UPDATE countries SET why_title = 'Why study in Malaysia?', why_body = '<p>Malaysia offers a lower cost of study than most Western destinations, English-medium teaching and a wide choice of public universities and branch campuses of foreign universities. Universiti Malaya is reported at 56th in the QS World University Rankings 2027.</p><ul><li>Lower tuition and living costs than the UK, Australia and the US</li><li>International branch campuses such as Monash and Nottingham give foreign degrees locally</li><li>Many courses taught fully in English</li><li>Easy travel across Southeast Asia</li></ul>', visa_title = 'Student pass requirements', visa_body = '<p>International students need a <strong>Student Pass</strong> through the Education Malaysia Global Services (<strong>EMGS</strong>). Your university submits the application for you, and you receive a Visa Approval Letter (VAL) before you travel.</p><ul><li>Offer letter from an approved Malaysian institution</li><li>Passport with enough validity (at least 18 months reported)</li><li>Medical screening at an approved clinic</li><li>EMGS and student pass fees: reported at roughly RM 2,650-3,850 including an RM 1,000 EMGS fee (sources vary)</li><li>Some nationalities need a Single-Entry Visa before arrival</li><li>Processing typically takes 4-6 weeks and sometimes longer</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official EMGS and the Immigration Department (imi.gov.my) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the university, which then handles your Student Pass through EMGS.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency result</li><li>Passport copy and photographs</li><li>Statement of purpose or CV for postgraduate courses</li><li>Portfolio or interview for some courses</li><li>Medical report and insurance for the pass</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs depend on the institution and course. Foreign branch campuses tend to cost more than local public universities.</p><ul><li>Tuition: roughly RM 20,000-RM 60,000 a year for most courses, higher for medicine and branch campuses</li><li>Living costs: roughly RM 1,500-RM 3,500 a month depending on the city</li><li>EMGS and visa costs: reported around RM 2,650-3,850</li><li>Health and personal accident insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements differ by level and institution.</p><ul><li><strong>Foundation / Diploma:</strong> completed secondary school with required grades</li><li><strong>Bachelor''s:</strong> a pre-university qualification such as A-levels, STPM, foundation or the Indian Class 12</li><li><strong>Master''s:</strong> a relevant bachelor''s degree with a minimum grade</li><li><strong>English:</strong> IELTS 5.5-6.5 or equivalent for most courses</li></ul>' WHERE slug = 'malaysia';
COMMIT;
